import { createInitialState, restoreState, ACTIONS, currentPlayer, getLegalCards, topCard } from './game-engine/engine.js';
import { COLORS } from './game-engine/cards.js';
import { LocalGameTransport } from './platform/transport.js';
import { loadSettings, saveSettings, saveMatch, loadMatch, clearMatch, feedback } from './platform/storage.js';
import { runBotStep, chooseColor } from './game-ai/bot.js';
import { cardHTML } from './ui/card.js';

const root=document.querySelector('#app');
const colorHex={red:'#ef5546',blue:'#3697e8',green:'#45ae65',yellow:'#f4cf34'};
const colorName={red:'אדום',blue:'כחול',green:'ירוק',yellow:'צהוב'};
let settings=loadSettings(),transport=null,state=null,view='home',sheet=null,selected=null,hint='',botTimer=null,eventTimer=null,eventBanner=null,lastLogLength=0;

function startGame(saved=null){
  try{state=saved?restoreState(JSON.stringify(saved)):createInitialState({playerCount:settings.playerCount,seed:Date.now()});}
  catch{clearMatch();state=createInitialState({playerCount:settings.playerCount,seed:Date.now()});}
  transport?.disconnect();transport=new LocalGameTransport(state);view='game';sheet=null;eventBanner=null;lastLogLength=state.log.length;
  transport.subscribeToState((next,action)=>{state=next;saveMatch(state);onState(action);render();scheduleGame();});
}
function submit(action){if(eventBanner)return;try{transport.submitAction(action);selected=null;}catch{hint='הקלף הזה לא מתאים עכשיו';feedback('invalid',settings);render();setTimeout(()=>{hint='';render();},1100);}}
function showEvent(title,detail='',kind=''){clearTimeout(eventTimer);eventBanner={title,detail,kind};eventTimer=setTimeout(()=>{eventBanner=null;render();scheduleGame();},settings.reducedMotion?700:1550);}
function onState(action){
  const entries=state.log.slice(lastLogLength);lastLogLength=state.log.length;
  const latest=entries.at(-1),stop=entries.find(e=>e.type==='stop'),reverse=entries.find(e=>e.type==='reverse'),again=entries.find(e=>e.type==='playAgain'),penalty=entries.find(e=>e.type==='drawPenalty'),lastPenalty=entries.find(e=>e.type==='lastCardPenalty'),color=entries.find(e=>e.type==='color'),takiPassed=entries.find(e=>e.type==='takiPassed');
  if(stop)showEvent('עצור!',`${state.players.find(p=>p.id===stop.skipped)?.name} מדלג על התור`,'stop');
  else if(reverse)showEvent('משנים כיוון','סדר המשחק התהפך','reverse');
  else if(again)showEvent('עוד תור','אותו שחקן ממשיך','again');
  else if(penalty)showEvent(`${penalty.amount}+ קלפים`,'העונש נמשך מהקופה','penalty');
  else if(lastPenalty)showEvent('שכחתם ״קלף אחרון״',`${lastPenalty.amount} קלפי קנס`,'penalty');
  else if(color)showEvent(`הצבע עכשיו ${colorName[color.color]}`,'ממשיכים לפי הצבע החדש','color');
  else if(takiPassed)showEvent('TAKI נשאר פתוח',`אין המשך ב${colorName[takiPassed.color]} — עוברים לשחקן הבא`,'taki');
  if(entries.length)feedback(['stop','reverse','playAgain','drawPenalty'].includes(latest?.type)?'special':'play',settings);
  if(action.type===ACTIONS.DRAW)feedback('draw',settings);
}
function delay(){return settings.difficulty==='quick'?800:settings.difficulty==='thoughtful'?1900:1250;}
function scheduleGame(){
  clearTimeout(botTimer);if(!state||state.phase==='finished'||eventBanner)return;
  botTimer=setTimeout(()=>{const active=currentPlayer(state);if(state.awaitingColor&&active.kind==='ai'){submit({type:ACTIONS.CHOOSE_COLOR,playerId:active.id,color:chooseColor(active.hand)});return;}if(active.kind==='ai'){try{const next=runBotStep(state);transport.state=next;state=next;transport.listeners.forEach(fn=>fn(state,{type:'bot'}));}catch{submit({type:ACTIONS.DRAW,playerId:active.id});}}},delay());
}

function homeHTML(){const saved=loadMatch();return `<main class="app-shell" dir="rtl"><section class="home"><div class="home-top"><button class="icon-btn" data-open="settings" aria-label="הגדרות"><span class="gear"></span></button></div><div class="brand"><div class="brand-mark" aria-label="TAKI"><span>T</span><span>A</span><span>K</span><span>I</span></div><p>משחק קלפים בכיס</p></div><div class="setup-card">${saved&&saved.phase!=='finished'?'<button class="primary resume" data-resume>המשך משחק</button>':''}<div class="setup-row"><label>מספר שחקנים</label><div class="segmented" role="group" aria-label="מספר שחקנים">${[2,3,4,6,8,10].map(n=>`<button data-players="${n}" class="${settings.playerCount===n?'on':''}">${n}</button>`).join('')}</div></div><div class="setup-row"><label for="difficulty">קצב היריבים</label><select id="difficulty" class="select"><option value="quick" ${settings.difficulty==='quick'?'selected':''}>מהיר</option><option value="normal" ${settings.difficulty==='normal'?'selected':''}>רגוע</option><option value="thoughtful" ${settings.difficulty==='thoughtful'?'selected':''}>איטי</option></select></div><button class="primary" data-play>מתחילים</button><button class="text-btn" data-open="rules">איך משחקים?</button></div></section>${sheetHTML()}</main>`;}
function opponentHTML(player,slot='top'){const active=currentPlayer(state).id===player.id,stopped=state.log.at(-1)?.type==='stop'&&state.log.at(-1).skipped===player.id;const count=Math.min(9,player.hand.length),backs=Array.from({length:count},(_,i)=>`<i style="--offset:${i-(count-1)/2}"></i>`).join('');return `<div class="opponent seat-${slot} ${active?'active':''} ${stopped?'skipped':''}"><div class="player-tag"><span>${player.name}</span><strong>${player.hand.length}</strong></div><div class="opponent-fan">${backs}</div></div>`;}
function opponentSeats(players){const layouts={1:['top'],2:['left','right'],3:['left','top','right'],4:['far-left','left','right','far-right'],5:['far-left','left','top','right','far-right']};return players.map((player,i)=>opponentHTML(player,(layouts[players.length]||layouts[5])[i]||'top')).join('');}
function statusHTML(){const items=[];if(state.activePenalty)items.push(`<span class="status-pill penalty">${state.activePenalty.amount}+</span>`);if(state.taki?.open)items.push(`<span class="status-pill taki">TAKI פתוח · ${colorName[state.taki.color]}</span>`);if(state.freePlay)items.push('<span class="status-pill">קלף חופשי</span>');if(state.mustPlayAgain&&!state.taki)items.push('<span class="status-pill">משחקים שוב</span>');return items.join('');}
function humanControls(){const human=state.players[0],isTurn=currentPlayer(state).id===human.id&&!eventBanner,parts=[];if(state.lastCardWindow?.playerId===human.id&&!state.lastCardWindow.declared)parts.push('<button class="action-chip alert" data-last>קלף אחרון!</button>');if(isTurn&&state.taki?.open&&(state.taki.lastCardId||(state.taki.ownerId===human.id&&state.taki.openedTurn===state.turn)))parts.push(`<button class="action-chip dark" data-close>${state.taki.lastCardId?'סוגרים TAKI':'משאירים פתוח'}</button>`);if(isTurn&&state.mustPlayAgain&&!state.taki&&getLegalCards(state,human.id).length===0)parts.push('<button class="action-chip" data-end>משיכה וסיום תור</button>');return parts.length?`<div class="floating-actions">${parts.join('')}</div>`:'';}
function choiceHTML(){if(state.awaitingColor?.playerId!=='p0')return'';return `<div class="reaction"><div class="reaction-card"><h2>איזה צבע ממשיך?</h2><p>בחרו את הצבע שיוביל את התור הבא.</p><div class="color-picker">${COLORS.map(c=>`<button class="${c}" data-color="${c}" aria-label="${colorName[c]}"></button>`).join('')}</div></div></div>`;}
function eventHTML(){return eventBanner?`<div class="board-event ${eventBanner.kind}"><div class="event-mark"></div><strong>${eventBanner.title}</strong><span>${eventBanner.detail}</span></div>`:'';}
function gameHTML(){
  const human=state.players[0],active=currentPlayer(state),isHumanTurn=active.id===human.id&&!state.awaitingColor&&!eventBanner,legal=new Set(isHumanTurn?getLegalCards(state,human.id).map(c=>c.id):[]);
  const shown=human.hand.slice(0,12),more=human.hand.length-shown.length,top=topCard(state),turnHint=hint||(state.activePenalty&&isHumanTurn?`אפשר להניח 2+ או מלך — או למשוך ${state.activePenalty.amount}`:state.taki?.open&&isHumanTurn?`TAKI פתוח ב${colorName[state.taki.color]} — ממשיכים רק באותו צבע`:isHumanTurn?'התאימו צבע, מספר או סמל':`ממתינים ל${active.name}`),visibleOpponents=state.players.slice(1,6),hiddenOpponents=Math.max(0,state.players.length-1-visibleOpponents.length);
  return `<main class="app-shell table-shell" dir="rtl" style="--active:${colorHex[state.activeColor]||'#22c6eb'}"><section class="game ${isHumanTurn?'human-turn':'waiting'}"><header class="game-head"><button class="table-menu" data-open="pause" aria-label="תפריט והשהיה"><i></i><i></i><i></i></button><div class="turn-banner ${isHumanTurn?'mine':''}"><small>עכשיו משחקים</small><strong>${isHumanTurn?'התור שלכם':active.name}</strong><b>${active.hand.length}</b></div></header><div class="board"><div class="table-ring"></div><div class="opponents">${opponentSeats(visibleOpponents)}${hiddenOpponents?`<div class="opponent seat-extra"><div class="player-tag"><span>נוספים</span><strong>${hiddenOpponents}+</strong></div></div>`:''}</div><div class="center"><div class="direction ${state.direction<0?'counter':''}" aria-label="${state.direction<0?'נגד כיוון השעון':'עם כיוון השעון'}"><i></i><i></i></div><div class="status-stack">${statusHTML()}</div><div class="pile discard">${cardHTML(top)}<span class="pile-label">${colorName[state.activeColor]||'חופשי'}</span></div><button class="pile draw-pile" data-draw aria-label="משיכת קלף"><span class="brand-mini">TAKI</span><span class="pile-label">קופה · ${state.drawPile.length}</span></button>${eventHTML()}</div></div><footer class="hand-area"><div class="hand-meta"><span class="hint">${turnHint}</span>${more?`<span class="hint">ועוד ${more}</span>`:''}</div><div class="hand">${shown.map((card,i)=>cardHTML(card,{legal:isHumanTurn&&legal.has(card.id),selected:selected===card.id,index:i,total:shown.length})).join('')}</div></footer></section>${humanControls()}${choiceHTML()}${state.phase==='finished'?winHTML():''}${sheetHTML()}</main>`;
}
function winHTML(){const winner=state.players.find(p=>p.id===state.winnerId);return `<div class="win"><div class="win-card"><div class="win-burst">TAKI!</div><h1>${winner?.id==='p0'?'ניצחתם!':winner?.name+' ניצח'}</h1><p>${state.turn} תורים · ${state.log.filter(x=>x.type==='play').length} קלפים שוחקו</p><button class="primary" data-rematch>משחק נוסף</button><button class="text-btn" data-home>מסך הבית</button></div></div>`;}
function sheetHTML(){if(!sheet)return'';if(sheet==='rules')return `<div class="sheet-wrap"><article class="sheet"><div class="grab"></div><h2>איך משחקים?</h2><p>מניחים קלף באותו צבע, מספר או סמל של הקלף המוביל. אם מושכים קלף, אפשר להשתמש בו רק בתור הבא. הראשון שנפטר מכל הקלפים מנצח.</p><h3>TAKI</h3><p>TAKI פותח רצף בצבע שלו בלבד. אי־אפשר לעבור ממנו ל־TAKI בצבע אחר. אם אין לכם קלף נוסף בצבע הזה, התור עובר אוטומטית וה־TAKI נשאר פתוח לשחקן הבא. אחרי שמניחים קלפים במפל, סוגרים אותו במפורש; רק הפקודה בקלף האחרון מתבצעת.</p><h3>קלפים מיוחדים</h3><p><b>עצור</b> מדלג על השחקן הבא. <b>שנה כיוון</b> הופך את סדר המשחק. <b>פלוס</b> נותן תור נוסף. <b>2+</b> מצטבר עד שמישהו מושך. <b>שנה צבע</b> בוחר צבע חדש. <b>סופר TAKI</b> מקבל את צבע הקלף שמתחתיו.</p><p><b>מלך</b> מבטל את ההגבלה הנוכחית ופותח משחק חופשי נוסף.</p><h3>קלף אחרון</h3><p>כשנשאר לכם קלף אחד, לחצו על ״קלף אחרון!״ לפני שהשחקן הבא מסיים פעולה. אחרת מושכים ארבעה.</p><button class="primary" data-close-sheet>הבנתי</button></article></div>`;return `<div class="sheet-wrap"><article class="sheet"><div class="grab"></div><h2>${sheet==='pause'?'המשחק מושהה':'הגדרות'}</h2>${toggleRow('צלילים','sound')}${toggleRow('רטט','haptics')}${toggleRow('צמצום תנועה','reducedMotion')}${sheet==='pause'?'<button class="primary" data-close-sheet>ממשיכים לשחק</button><button class="text-btn" data-home>שמירה וחזרה לבית</button>':'<button class="primary" data-close-sheet>סיום</button>'}</article></div>`;}
function toggleRow(label,key){return `<div class="setup-row"><label>${label}</label><button class="switch ${settings[key]?'on':''}" data-toggle="${key}" aria-pressed="${settings[key]}"></button></div>`;}

function render(){root.innerHTML=view==='home'?homeHTML():gameHTML();bind();}
function bind(){
  root.querySelectorAll('[data-open]').forEach(button=>button.onclick=()=>{sheet=button.dataset.open;render();});root.querySelectorAll('[data-close-sheet]').forEach(button=>button.onclick=()=>{sheet=null;render();});root.querySelectorAll('[data-toggle]').forEach(button=>button.onclick=()=>{settings[button.dataset.toggle]=!settings[button.dataset.toggle];saveSettings(settings);render();});root.querySelectorAll('[data-players]').forEach(button=>button.onclick=()=>{settings.playerCount=+button.dataset.players;saveSettings(settings);render();});
  const difficulty=root.querySelector('#difficulty');if(difficulty)difficulty.onchange=()=>{settings.difficulty=difficulty.value;saveSettings(settings);};
  root.querySelector('[data-play]')?.addEventListener('click',()=>{clearMatch();startGame();});root.querySelector('[data-resume]')?.addEventListener('click',()=>startGame(loadMatch()));root.querySelectorAll('[data-home]').forEach(button=>button.onclick=()=>{clearTimeout(botTimer);clearTimeout(eventTimer);eventBanner=null;view='home';sheet=null;render();});root.querySelector('[data-rematch]')?.addEventListener('click',()=>{clearMatch();startGame();});
  root.querySelector('[data-draw]')?.addEventListener('click',()=>{if(currentPlayer(state).id==='p0'&&!eventBanner)submit({type:ACTIONS.DRAW,playerId:'p0'});});root.querySelector('[data-last]')?.addEventListener('click',()=>submit({type:ACTIONS.DECLARE_LAST,playerId:'p0'}));root.querySelector('[data-close]')?.addEventListener('click',()=>submit({type:ACTIONS.CLOSE_TAKI,playerId:'p0'}));root.querySelector('[data-end]')?.addEventListener('click',()=>submit({type:ACTIONS.END_TURN,playerId:'p0'}));root.querySelectorAll('[data-color]').forEach(button=>button.onclick=()=>submit({type:ACTIONS.CHOOSE_COLOR,playerId:'p0',color:button.dataset.color}));
  root.querySelectorAll('.hand .card.legal').forEach(card=>{let startY=0,moved=false;card.onclick=e=>{if(e.detail===0)submit({type:ACTIONS.PLAY,playerId:'p0',cardId:card.dataset.cardId});};card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();submit({type:ACTIONS.PLAY,playerId:'p0',cardId:card.dataset.cardId});}};card.onpointerdown=e=>{startY=e.clientY;moved=false;card.setPointerCapture(e.pointerId);selected=card.dataset.cardId;card.classList.add('selected');};card.onpointermove=e=>{if(!card.hasPointerCapture(e.pointerId))return;const dy=e.clientY-startY;if(Math.abs(dy)>8)moved=true;card.style.transform=`translateY(${Math.min(0,dy)}px) rotate(0)`;};card.onpointerup=e=>{const dy=e.clientY-startY;card.releasePointerCapture(e.pointerId);if(dy<-72||!moved)submit({type:ACTIONS.PLAY,playerId:'p0',cardId:card.dataset.cardId});else render();};});
}
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
function registerWebMCP(){const context=document.modelContext;if(!context?.registerTool)return;const register=tool=>{try{void Promise.resolve(context.registerTool(tool)).catch(()=>{});}catch{}};register({name:'read_game_state',title:'Read TAKI game',description:'Read the current match status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return state?{phase:state.phase,currentPlayer:currentPlayer(state).name,activeColor:state.activeColor,humanCardCount:state.players[0].hand.length,opponents:state.players.slice(1).map(p=>({name:p.name,cardCount:p.hand.length})),takiOpen:!!state.taki,penalty:state.activePenalty?.amount||0}:{phase:'home'};}});}
registerWebMCP();render();
